#include "document.h"
#include "brush_dynamics.h"
#include <iostream>
#include <stdexcept>
using namespace moon;
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
int main(){try{
 dynamics::Settings s;check(dynamics::resolve(s,{.5,0,true},10).size==10,"default dynamics disabled");dynamics::selectSensor(s,0,dynamics::Sensor::Pressure);check(s.effects[0].inputMin==10&&s.effects[0].inputMax==90&&s.effects[0].outputMin==0,"factory pressure range and one pixel floor");for(auto pair:{std::pair<double,int>{.1,1},{.5,5},{.9,10}})check(dynamics::resolve(s,{pair.first,0,true},10).size==pair.second,"legacy pressure fixture");check(dynamics::resolve(s,{.5,0,false},10).size==10,"absent hardware full base size");check(!dynamics::reliablePressure(false,false,0)&&!dynamics::reliablePressure(false,false,.5)&&!dynamics::reliablePressure(false,true,.8)&&dynamics::reliablePressure(true,false,0),"mouse and touch conservative pressure");s.effects[0].curve=dynamics::Curve::Soft;check(dynamics::resolve(s,{.3,0,true},20).size==10,"soft sqrt fixture");s.effects[0].curve=dynamics::Curve::Hard;check(dynamics::resolve(s,{.5,0,true},20).size==5,"hard squared fixture");s.effects[0].inverse=true;check(dynamics::resolve(s,{.1,0,true},20).size==20,"inverse fixture");s.effects[0].inputMax=s.effects[0].inputMin;check(dynamics::resolve(s,{.1,0,true},20).size==1,"equal threshold inverse");
 std::optional<dynamics::SpeedState> speed;check(dynamics::trackSpeed(speed,0,0,0)==0,"speed starts zero");const auto expected=1000*(1-std::exp(-10./55));check(std::abs(dynamics::trackSpeed(speed,10,0,10)-expected)<1e-9,"55ms EMA fixture");check(dynamics::trackSpeed(speed,1000,0,170)==0,"160ms speed reset");check(dynamics::smoothSize(1,64,12,1)==3,"integer size envelope");
 Document d(32,16);BrushOptions b;b.size=9;d.beginStroke({2,8},0xff112233,b,nullptr,0,nullptr,false);d.configureStrokeDynamics(b,nullptr,0xff000000,0xffffffff,0);d.updateDynamicStroke({2,8},{2,8,1,20,0,{}},true);d.updateDynamicStroke({20,8},{20,8,9,100,0,{}});check(d.historySize()==0&&d.pixels()[8*32+20]==0xff112233,"live dynamic size/strength transaction");check(d.pixels()[4*32+20]!=0&&d.pixels()[4*32+2]==0,"interpolated size footprint");check(d.commitStroke()&&d.historySize()==1,"one dynamic history");const auto after=d.pixels();d.undo();check(d.pixels()==std::vector<Pixel>(512),"dynamic whole undo");d.redo();check(d.pixels()==after,"dynamic redo");
 d.beginStroke({2,8},0,b,nullptr,0,nullptr,false);d.configureStrokeDynamics(b,nullptr,0,0,0);d.updateDynamicStroke({2,8},{2,8,4,50,0,{}},true);d.cancelStroke();check(d.pixels()==after&&d.historySize()==1,"dynamic cancel");
 Document gradient(8,4);b.size=1;gradient.beginStroke({0,1},0xffffffff,b,nullptr,0,nullptr,false);gradient.configureStrokeDynamics(b,nullptr,0xff000000,0xffffffff,0);gradient.updateDynamicStroke({0,1},{0,1,1,100,0,0.},true);gradient.updateDynamicStroke({7,1},{7,1,1,100,0,1.});check(gradient.pixels()[8]==0xff000000&&gradient.pixels()[15]==0xffffffff&&gradient.pixels()[11]==0xff6d6d6d,"dynamic gradient per-stamp interpolation");gradient.commitStroke();
 Document pp(16,16);b.size=1;b.perfectPixels=true;pp.beginStroke({2,2},0xff00ffff,b,nullptr,0,nullptr,false);pp.configureStrokeDynamics(b,nullptr,0,0,0);pp.updateDynamicStroke({2,2},{2,2,1,100,0,{}},true);pp.updateDynamicStroke({3,2},{3,2,1,100,0,{}});pp.updateDynamicStroke({3,3},{3,3,1,100,0,{}});check(pp.pixels()[2*16+3]==0&&pp.pixels()[3*16+3]!=0,"perfect pixel dynamic reversible tail");pp.cancelStroke();check(pp.pixels()==std::vector<Pixel>(256),"perfect dynamic cancellation");
 std::cout<<"brush dynamics tests passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
